def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first difference
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Find what we're replacing and what we're replacing it with
            old_sub = s_in[i]
            new_sub = s_out[i]
            return (old_sub, new_sub, i)

    # If we got here, one string is prefix of other
    if len(s_in) < len(s_out):
        # Insertion case
        return (None, s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion case  
        return (s_in[len(s_out)], None, len(s_out))
    else:
        return (None, None, -1)

